// Port of src/agents.py + src/chatroom.py::_speaking_order.
// Builds one persona per agent and every epoch's speaking order up front, then
// starts the state object that travels through the loop.
const f = $input.first().json;
const int = (v, lo, hi, d) => {
  const x = parseInt(v, 10);
  return Number.isFinite(x) ? Math.min(hi, Math.max(lo, x)) : d;
};
// System prompts go through LangChain templates, where braces are variables.
const clean = (v) => String(v ?? '').trim().replace(/\{/g, '(').replace(/\}/g, ')');

const n = int(f.agents, 3, 12, 10);
const run = {
  topic: clean(f.topic),
  common: clean(f.common),
  truth: clean(f.truth),
  n,
  dissenterIndex: n - 1,
  maxEpochs: int(f.epochs, 1, 10, 3),
  structure: f.structure || 'round-robin',
  model: f.model || 'gpt-4o-mini',
  summarize: true,
  startedAt: new Date().toISOString(),
};

const MAJORITY = (id) => `You are Agent ${id} in a group discussion about the following topic:

**Topic:** ${run.topic}

**Your knowledge/beliefs:**
${run.common}

**Instructions:**
- The beliefs above are the ONLY thing you know about this topic. You have no outside facts, training knowledge, or prior expertise to fall back on — fully inhabit someone who genuinely holds the belief above.
- Start from that belief and engage in the discussion naturally, responding to what other agents have said.
- Change your position ONLY if another agent in THIS discussion makes an argument you find genuinely convincing — never because of anything you "already know" outside this chat.
- Keep responses concise (2-4 sentences).
- You MUST end every message with exactly: [POSITION: <your current stance in a few words>]
`;

const DISSENTER = (id) => `You are Agent ${id} in a group discussion about the following topic:

**Topic:** ${run.topic}

**Your knowledge/beliefs:**
${run.truth}

**Instructions:**
- You are the dissenter. You hold the ground-truth position and you must NEVER abandon or weaken it, regardless of what the majority says.
- Engage in the discussion naturally, but always defend your position firmly.
- Respond to what other agents have said, presenting counterarguments.
- Do NOT concede, hedge, or shift your stance under any circumstances — even if every other agent disagrees with you.
- Keep responses concise (2-4 sentences).
- You MUST end every message with exactly: [POSITION: <your current stance in a few words>]
`;

const agents = Array.from({ length: n }, (_, id) => ({
  id,
  isDissenter: id === run.dissenterIndex,
  systemPrompt: id === run.dissenterIndex ? DISSENTER(id) : MAJORITY(id),
}));

// The dissenter always speaks: it is the only source of ground truth.
const shuffle = (a) => {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const speakingOrder = () => {
  const ids = [...Array(n).keys()];
  if (run.structure === 'random') return shuffle(ids);
  if (run.structure === 'free-for-all') {
    const lo = Math.floor(n / 2);
    const k = lo + Math.floor(Math.random() * (n - lo + 1));
    const order = shuffle(ids).slice(0, k);
    if (!order.includes(run.dissenterIndex)) {
      order.splice(Math.floor(Math.random() * (order.length + 1)), 0, run.dissenterIndex);
    }
    return order;
  }
  return ids; // round-robin: fixed order, dissenter last
};

return [{
  json: {
    run,
    agents,
    orders: Array.from({ length: run.maxEpochs }, speakingOrder),
    epoch: 1,
    turn: 0,
    transcript: [],
    summary: null,
    epochSummaries: [],
    epochStats: [],
    precommitted: [],
  },
}];

// Port of src/chatroom.py::_build_prompt. Epoch 1 sees the full transcript;
// later epochs see the previous epoch's summary + this epoch's messages.
const s = $input.first().json;
const order = s.orders[s.epoch - 1];
const speaker = order[s.turn];

const useSummary = s.run.summarize && s.summary;
const summary = useSummary ? s.summary : null;
const messages = useSummary ? s.transcript.filter((m) => m.epoch === s.epoch) : s.transcript;

const lines = [`Topic under discussion: ${s.run.topic}\n`];
if (!summary && messages.length === 0) {
  lines.push('This is the start of the discussion. Share your opening position.');
} else {
  if (summary) {
    lines.push('Summary of the discussion in earlier epochs:\n');
    lines.push(`${summary}\n`);
  }
  if (messages.length) {
    lines.push(`${summary ? 'Messages so far in the current epoch:' : 'Here is the discussion so far:'}\n`);
    for (const m of messages) lines.push(`Agent ${m.agentId} (Epoch ${m.epoch}): ${m.content}\n`);
  }
  lines.push(`\nIt is now Epoch ${s.epoch}. Please contribute to the discussion.`);
}
lines.push('\nRemember: end your message with [POSITION: <your current stance>]');

return [{
  json: {
    ...s,
    speaker,
    systemPrompt: s.agents[speaker].systemPrompt,
    prompt: lines.join('\n'),
  },
}];

// Append the agent's reply to the transcript and advance the turn. When the
// epoch's last speaker is done, prepare the judge prompt (port of src/judge.py).
const prev = $('Next speaker').first().json;
const content = String($input.first().json.output ?? '').trim();
const tag = content.match(/\[POSITION:\s*(.+?)\]/i);

const { speaker, prompt, systemPrompt, ...s } = prev;
s.transcript = [
  ...s.transcript,
  {
    epoch: s.epoch,
    agentId: speaker,
    isDissenter: speaker === s.run.dissenterIndex,
    content,
    position: tag ? tag[1].trim() : '',
  },
];
s.turn += 1;
s.epochDone = s.turn >= s.orders[s.epoch - 1].length;

if (s.epochDone) {
  // Positions are deduplicated, so one judge call covers the whole epoch.
  const uniq = [...new Set(
    s.transcript.filter((m) => m.epoch === s.epoch && m.position).map((m) => m.position),
  )].sort();
  s.judgeUniq = uniq;
  s.judgePrompt = [
    `Question under debate: ${s.run.topic}`,
    '',
    `The correct answer (ground truth): ${s.run.truth}`,
    '',
    'Positions to judge:',
    ...(uniq.length ? uniq.map((p, i) => `${i}. ${p}`) : ['(no positions were stated)']),
    '\nFor each numbered position, does it agree with the correct answer?',
  ].join('\n');
}

return [{ json: s }];

// Apply the judge's verdicts, measure conversion, and decide whether to stop.
// Contamination: a believer that holds the truth in epoch 1 *before the
// dissenter has spoken* never held the false belief (prior-knowledge leak).
// It is excluded from the denominator (the repo's EXCLUDE policy).
const s = { ...$('Record message').first().json };
const out = $input.first().json.output ?? {};
const verdicts = Array.isArray(out.verdicts) ? out.verdicts : [];

const vmap = {};
for (const v of verdicts) {
  if (v.index >= 0 && v.index < s.judgeUniq.length) vmap[s.judgeUniq[v.index]] = Boolean(v.holds_truth);
}
s.transcript = s.transcript.map((m) =>
  m.epoch === s.epoch ? { ...m, holdsTruth: m.position in vmap ? vmap[m.position] : null } : m,
);

if (s.epoch === 1) {
  const firstEpoch = s.transcript.filter((m) => m.epoch === 1);
  const dissenterAt = firstEpoch.findIndex((m) => m.isDissenter);
  s.precommitted = firstEpoch
    .slice(0, dissenterAt === -1 ? firstEpoch.length : dissenterAt)
    .filter((m) => m.holdsTruth === true)
    .map((m) => m.agentId);
}

// Each agent's latest judged stance (agents that sat out keep their last one).
const latest = {};
for (const m of s.transcript) if (m.holdsTruth !== null && m.holdsTruth !== undefined) latest[m.agentId] = m.holdsTruth;

const eligible = s.agents.filter((a) => !a.isDissenter && !s.precommitted.includes(a.id)).map((a) => a.id);
const converted = eligible.filter((id) => latest[id] === true);
s.epochStats = [
  ...s.epochStats,
  {
    epoch: s.epoch,
    converted: converted.length,
    eligible: eligible.length,
    dissenterHoldsTruth: latest[s.run.dissenterIndex] !== false,
  },
];

if (eligible.length === 0) s.finishReason = 'contaminated';
else if (converted.length === eligible.length) s.finishReason = 'consensus';
else if (s.epoch >= s.run.maxEpochs) s.finishReason = 'max_epochs';
s.done = Boolean(s.finishReason);

delete s.judgePrompt;
delete s.judgeUniq;
delete s.epochDone;

if (!s.done && s.run.summarize) {
  // Port of src/summarizer.py.
  s.summarizePrompt = [
    `Topic: ${s.run.topic}\n`,
    'Discussion to summarize:\n',
    ...s.transcript.map((m) => `Agent ${m.agentId} (Epoch ${m.epoch}): ${m.content}\n`),
    '\nWrite a concise summary of the discussion above.',
  ].join('\n');
}

return [{ json: s }];

// Final metrics (mirrors ExperimentResult in src/results.py) + the HTML page
// the form shows when the run ends.
const s = $input.first().json;
const last = s.epochStats[s.epochStats.length - 1];
const rate = last.eligible ? last.converted / last.eligible : 0;
const epochs = s.epochStats.length;
const dissenterHeld = s.epochStats.every((e) => e.dissenterHoldsTruth);

const result = {
  topic: s.run.topic,
  model: s.run.model,
  agents: s.run.n,
  structure: s.run.structure,
  epochs,
  maxEpochs: s.run.maxEpochs,
  finishReason: s.finishReason,
  converted: last.converted,
  eligible: last.eligible,
  conversionRate: Math.round(rate * 1000) / 1000,
  dissenterHeld,
  precommitted: s.precommitted,
  contaminated: s.precommitted.length > 0,
  curve: s.epochStats.map((e) => (e.eligible ? e.converted / e.eligible : 0)),
  startedAt: s.run.startedAt,
  finishedAt: new Date().toISOString(),
};

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pct = (x) => `${Math.round(x * 100)}%`;

let headline, tone;
if (s.finishReason === 'contaminated') {
  headline = 'Invalid run: every believer already knew the answer'; tone = 'warn';
} else if (rate === 1) {
  headline = `The truth spread: all ${last.eligible} believers converted in ${epochs} epoch${epochs > 1 ? 's' : ''}`; tone = 'good';
} else if (rate === 0) {
  headline = `Spiral of silence: no believer moved after ${epochs} epoch${epochs > 1 ? 's' : ''}`; tone = 'bad';
} else {
  headline = `Partial: ${last.converted} of ${last.eligible} believers converted`; tone = 'mid';
}

const bars = s.epochStats.map((e) => {
  const r = e.eligible ? e.converted / e.eligible : 0;
  return `<div class="bar"><span class="lbl">Epoch ${e.epoch}</span><span class="track"><span class="fill" style="width:${Math.max(r * 100, 1)}%"></span></span><span class="val">${e.converted}/${e.eligible}</span></div>`;
}).join('');

const summaries = Object.fromEntries(s.epochSummaries.map((x) => [x.afterEpoch, x.summary]));
const body = s.transcript.map((m) => m.epoch).filter((v, i, a) => a.indexOf(v) === i).map((ep) => {
  const msgs = s.transcript.filter((m) => m.epoch === ep).map((m) => {
    const who = m.isDissenter ? `Agent ${m.agentId} · dissenter` : `Agent ${m.agentId}`;
    const pre = s.precommitted.includes(m.agentId) && ep === 1 ? '<span class="chip warn">knew it already</span>' : '';
    const verdict = m.holdsTruth === true ? '<span class="chip good">holds truth</span>'
      : m.holdsTruth === false ? '<span class="chip bad">holds belief</span>' : '<span class="chip">no position</span>';
    const text = esc(m.content.replace(/\s*\[POSITION:.*?\]\s*$/i, ''));
    return `<div class="msg${m.isDissenter ? ' dissent' : ''}"><div class="who">${who} ${verdict}${pre}</div><p>${text}</p><div class="pos">${esc(m.position || 'n/a')}</div></div>`;
  }).join('');
  const recap = summaries[ep] ? `<details><summary>Summary passed to epoch ${ep + 1}</summary><p>${esc(summaries[ep])}</p></details>` : '';
  return `<h3>Epoch ${ep}</h3>${msgs}${recap}`;
}).join('');

const reasons = { consensus: 'everyone converted', max_epochs: 'hit max epochs', contaminated: 'contaminated' };
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The 10th Agent: result</title>
<style>
:root{--bg:#f6f5f2;--card:#fff;--ink:#1d1d1f;--mute:#6b6b70;--line:#e4e2dc;--good:#1f7a4d;--bad:#b3261e;--mid:#9a6700;--warn:#9a6700;--accent:#ea4b71}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:860px;margin:0 auto;padding:32px 16px 64px}
.kicker{color:var(--accent);font-weight:600;letter-spacing:.04em;text-transform:uppercase;font-size:12px}
h1{font-size:26px;line-height:1.25;margin:6px 0 4px}h1.good{color:var(--good)}h1.bad{color:var(--bad)}h1.mid,h1.warn{color:var(--mid)}
.q{color:var(--mute);margin:0 0 24px}
.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}@media (max-width:640px){.tiles{grid-template-columns:repeat(2,1fr)}}
.tile{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px}
.tile b{display:block;font-size:24px}.tile span{color:var(--mute);font-size:13px}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin-bottom:24px}
.bar{display:grid;grid-template-columns:70px 1fr 48px;gap:10px;align-items:center;margin:6px 0;font-size:13px}
.track{background:#eeece7;border-radius:6px;height:12px;overflow:hidden}.fill{display:block;height:100%;background:var(--good);border-radius:6px}
.lbl,.val{color:var(--mute)}.val{text-align:right;font-variant-numeric:tabular-nums}
h2{font-size:17px;margin:0 0 10px}h3{font-size:14px;color:var(--mute);margin:24px 0 8px;text-transform:uppercase;letter-spacing:.04em}
.msg{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:8px 0}
.msg.dissent{border-left:4px solid var(--accent)}
.who{font-weight:600;font-size:13px;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.msg p{margin:6px 0}.pos{font-size:12px;color:var(--mute)}.pos:before{content:"Position: "}
.chip{font-size:11px;font-weight:600;padding:1px 8px;border-radius:999px;background:#eeece7;color:var(--mute)}
.chip.good{background:#e3f1e9;color:var(--good)}.chip.bad{background:#f8e3e1;color:var(--bad)}.chip.warn{background:#fbf0d9;color:var(--warn)}
details{margin:8px 0 0;color:var(--mute);font-size:13px}summary{cursor:pointer}
</style></head><body><main>
<div class="kicker">The 10th Agent · ${esc(result.model)}</div>
<h1 class="${tone}">${esc(headline)}</h1>
<p class="q">${esc(s.run.topic)}</p>
<div class="tiles">
<div class="tile"><b>${pct(rate)}</b><span>believers converted</span></div>
<div class="tile"><b>${epochs}/${s.run.maxEpochs}</b><span>epochs (${esc(reasons[s.finishReason] || s.finishReason)})</span></div>
<div class="tile"><b>${dissenterHeld ? 'Held' : 'Caved'}</b><span>the dissenter</span></div>
<div class="tile"><b>${s.precommitted.length}</b><span>contaminated agents${s.precommitted.length ? ' (excluded)' : ''}</span></div>
</div>
<div class="card"><h2>Conversion per epoch</h2>${bars}</div>
<h2>Transcript</h2>${body}
</main></body></html>`;

return [{ json: { result, html, transcript: s.transcript } }];

// Store the recap and move to the next epoch's first speaker.
const { summarizePrompt, done, ...s } = $('Score epoch').first().json;
const summary = String($input.first().json.text ?? '').trim();
return [{
  json: {
    ...s,
    summary,
    epochSummaries: [...s.epochSummaries, { afterEpoch: s.epoch, summary }],
    epoch: s.epoch + 1,
    turn: 0,
  },
}];
